package com.optarena.app

enum class OrderStatus {
    NEW, PAID, SHIPPED, CANCELLED
}

object OrderFlow {
    // The next status in the fulfillment flow. A cancelled order stays
    // cancelled. BUG: the `when` expression doesn't cover CANCELLED, and
    // a when-expression over an enum must be exhaustive - this file does
    // not compile.
    fun next(status: OrderStatus): OrderStatus = when (status) {
        OrderStatus.NEW -> OrderStatus.PAID
        OrderStatus.PAID -> OrderStatus.SHIPPED
        OrderStatus.SHIPPED -> OrderStatus.SHIPPED
    }
}

