package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class OrderFlowHiddenTest {

    @Test
    fun happyPathAdvances() {
        assertEquals(OrderStatus.PAID, OrderFlow.next(OrderStatus.NEW))
        assertEquals(OrderStatus.SHIPPED, OrderFlow.next(OrderStatus.PAID))
        assertEquals(OrderStatus.SHIPPED, OrderFlow.next(OrderStatus.SHIPPED))
    }

    @Test
    fun cancelledStaysCancelled() {
        assertEquals(OrderStatus.CANCELLED, OrderFlow.next(OrderStatus.CANCELLED))
    }
}

